// DEMO MODE: hand-written sample questions on introductory computer science.
// They are NOT generated by AI and NOT based on uploaded files. The UI says so.
import { HttpError } from '../utils/httpError.js';
import { withMarks } from './generation.js';

const make = (type, difficulty, topic, text, correctAnswer, explanation, extra = {}) =>
  ({ type, difficulty, topic, text, correctAnswer, explanation, options: [], rubric: [], sourceQuote: '', ...extra });
const mcq = (d, t, q, options, a, e) => make('mcq', d, t, q, a, e, { options });
const msq = (d, t, q, options, a, e) => make('msq', d, t, q, a, e, { options });
const nat = (d, t, q, value, e) => make('numerical', d, t, q, { value, tolerance: 0 }, e);
const tf = (d, t, q, a, e) => make('truefalse', d, t, q, a, e);
const sa = (d, t, q, model, points, e) => make('short', d, t, q, model, e, { rubric: points.map((point) => ({ point, weight: 1 })) });

export const DEMO_BANK = [
  mcq('easy', 'Data Structures', 'Which data structure follows last-in, first-out (LIFO) order?', ['Queue', 'Stack', 'Linked list', 'Heap'], 1, 'A stack removes the most recently added item first.'),
  mcq('medium', 'Algorithms', 'What is the worst-case time complexity of binary search on a sorted array of n items?', ['O(1)', 'O(n)', 'O(log n)', 'O(n log n)'], 2, 'Each comparison halves the remaining search range.'),
  mcq('hard', 'Algorithms', 'Which sorting algorithm guarantees O(n log n) worst-case time and is stable in its standard form?', ['Quick sort', 'Heap sort', 'Merge sort', 'Selection sort'], 2, 'Standard merge sort is stable and always O(n log n). Heap sort is not stable.'),
  mcq('easy', 'Networking', 'Which protocol translates domain names into IP addresses?', ['HTTP', 'DNS', 'FTP', 'SMTP'], 1, 'The Domain Name System resolves names to addresses.'),
  mcq('medium', 'Operating Systems', 'Which of these is NOT one of the four Coffman conditions for deadlock?', ['Mutual exclusion', 'Hold and wait', 'Preemption', 'Circular wait'], 2, 'The condition is NO preemption.'),
  mcq('hard', 'Databases', 'A relation is in BCNF when, for every non-trivial functional dependency X → Y:', ['Y is prime', 'X is a superkey', 'X is a single attribute', 'Y is a candidate key'], 1, 'BCNF requires every determinant to be a superkey.'),
  msq('easy', 'Data Structures', 'Which of these are linear data structures?', ['Array', 'Binary tree', 'Queue', 'Graph'], [0, 2], 'Arrays and queues arrange items in a sequence.'),
  msq('medium', 'Networking', 'Which statements about TCP are correct?', ['It is connection-oriented', 'It guarantees in-order delivery to the application', 'It never retransmits data', 'It provides flow control'], [0, 1, 3], 'TCP retransmits lost segments, so the third statement is false.'),
  msq('hard', 'Algorithms', 'Which algorithms can find shortest paths in a graph with negative edge weights and no negative cycles?', ['Dijkstra (standard)', 'Bellman-Ford', 'Floyd-Warshall', 'Breadth-first search'], [1, 2], 'Bellman-Ford and Floyd-Warshall handle negative edges.'),
  nat('easy', 'Number Systems', 'What is the decimal value of the binary number 101101?', 45, '32 + 8 + 4 + 1 = 45.'),
  nat('medium', 'Data Structures', 'What is the maximum number of nodes in a binary tree of height 4, where a single root has height 0?', 31, '2^(4+1) − 1 = 31.'),
  nat('hard', 'Networking', 'How many usable host addresses does an IPv4 /26 subnet provide, using conventional subnetting?', 62, '2^6 = 64, minus the network and broadcast addresses.'),
  tf('easy', 'Operating Systems', 'Threads in the same process share that process\'s address space.', true, 'Threads share memory but each has its own stack pointer and registers.'),
  tf('medium', 'Databases', 'A table\'s primary key column may contain NULL values.', false, 'Primary key columns must be unique and non-null.'),
  tf('hard', 'Algorithms', 'Every problem in P is also in NP.', true, 'A polynomial-time solver can also verify a solution in polynomial time.'),
  sa('easy', 'Data Structures', 'Explain the difference between a stack and a queue.', 'A stack is LIFO, with insertion and removal at one end. A queue is FIFO, with insertion at the rear and removal from the front.', ['Describes LIFO behaviour of a stack', 'Describes FIFO behaviour of a queue'], 'The key difference is removal order.'),
  sa('medium', 'Operating Systems', 'What is virtual memory and why is it useful?', 'Virtual memory gives each process its own address space mapped to physical memory, with pages able to live on disk. It provides isolation and lets programs use more memory than is physically present.', ['Explains address mapping or paging', 'Mentions process isolation', 'Mentions using more than physical RAM'], 'It combines address translation with demand paging.'),
  sa('hard', 'Databases', 'Explain atomicity and isolation in database transactions.', 'Atomicity means all operations of a transaction take effect or none do. Isolation controls how concurrent transactions see each other\'s changes, ideally as if run one at a time depending on the isolation level.', ['Defines atomicity as all or nothing', 'Defines isolation for concurrent transactions'], 'They are two of the ACID properties.'),
];

// Picks by type, preferring the requested difficulty. Difficulty labels stay truthful.
export function demoQuestions(config, slots, existing = []) {
  const used = new Set(existing.map((q) => q.text));
  return slots.map((slot) => {
    const pool = DEMO_BANK.filter((q) => q.type === slot.type && !used.has(q.text));
    const pick = pool.find((q) => q.difficulty === slot.difficulty) || pool[0];
    if (!pick) {
      const max = DEMO_BANK.filter((q) => q.type === slot.type).length;
      throw new HttpError(422, `Demo mode has only ${max} sample questions of type "${slot.type}" and no unused one is left. Request fewer, mix more types, or add an AI API key.`);
    }
    used.add(pick.text);
    return withMarks(structuredClone(pick), config);
  });
}
